function main(){if(ui.view==='projector'&&state.admin)return projector();let panel=!state.admin&&game().phase==='waiting'?briefingView():ui.view==='round'?roundView():ui.view==='council'?councilView():ui.view==='home'?homeView():ui.view==='news'?newsroom():ui.view==='content'?studio():ui.view==='tasks'?board():ui.view==='security'?security():ui.view==='admin'&&state.admin?adminView():ui.view==='participants'&&state.admin?renderParticipants(state):ui.view==='results'?reportsView():homeView();return `${navbar()}<div class="workspace">${sidebar()}<main class="content" id="content" data-screen="${ui.view}" tabindex="-1">${panel}<footer class="content-foot">DIGITAL VILLAGE · EVERY DECISION HAS CONSEQUENCES · RURALEM</footer></main></div>${bottomNav()}`;}
function render(force=false){
 if(!state||ui.busy&&!force)return;
 if(!active())rememberAuth();
 if(new URL(location.href).searchParams.has('security')){app.innerHTML=securityReveal();return;}
 for(const detail of app.querySelectorAll('details[data-key]'))ui.openDetails.set(detail.dataset.key,detail.open);
 if(state.archivedReport)$id('final-report-dialog')?.close();
 updateScreen(app,state.archivedReport?renderFinalReport(state.archivedReport)+'<button class="primary" data-action="join-next-game">Join the next game</button>':active()?main():prejoin());
 if(state.finalReport&&!state.finalReport.acknowledged&&!$id('final-report-dialog')?.open)showFinalReport();
 for(const detail of app.querySelectorAll('details[data-key]'))if(ui.openDetails.has(detail.dataset.key))detail.open=ui.openDetails.get(detail.dataset.key);
 updateResend();
}
function setConnection(lost){
 const changed=connectionLost!==lost;connectionLost=lost;
 document.body.toggleAttribute('data-offline',lost);
 const banner=$id('connection-banner');if(banner)banner.hidden=!lost;
 document.querySelectorAll('[data-live-label]').forEach(el=>el.textContent=liveLabel());
 if(changed&&!lost&&state)notice('Connected again. Your game state has been refreshed.');
}
async function refresh(force=false){
 if(ui.busy&&!force)return;
 const version=++refreshVersion;
 try{
  const nextState=await api('state?history='+(state?.historyVersion||0));
  if(!nextState.histories&&state?.histories)nextState.histories=state.histories;
  if(version!==refreshVersion||ui.busy&&!force)return;
  const phaseChanged=state?.game?.phase!==nextState.game.phase||state?.game?.round!==nextState.game.round;
  const revealChanged=state?.game?.newsRevealed!==nextState.game.newsRevealed||state?.game?.mediaRevealed!==nextState.game.mediaRevealed;
  const wasRound=state?.game?.round,beforeView=ui.view;
  const oldPending=new Set((state?.proposals||[]).filter(p=>p.status==='pending').map(p=>p.id));
  const newRequests=state&&nextState.me?.role==='mayor'&&(nextState.proposals||[]).filter(p=>p.status==='pending'&&!oldPending.has(p.id));
  previousVillages=new Map((state?.villages||[]).map(v=>[v.id,v]));receivedAt=Date.now();
  if(nextState.game.round===0&&wasRound>0){ui.reportsCache.clear();ui.reportRound=null;ui.reportVillage=null;}
  state=nextState;
  if(newRequests?.length)notice(`${newRequests.length} new council request(s). Open Council decisions to review and approve.`);
  if(state.latestRoundReport){ui.reportsCache.set(state.latestRoundReport.round,state.latestRoundReport);if(phaseChanged)ui.reportRound=state.latestRoundReport.round;}
  if(state.me&&phaseChanged&&(wasRound!==state.game.round||['review','ended','waiting'].includes(state.game.phase))){ui.view=state.game.phase==='ended'&&state.finalReport?.acknowledged?'home':['review','ended'].includes(state.game.phase)?'results':state.game.round?'round':'home';}
  if(ui.view==='results')await loadReport();
  setConnection(false);render(force||phaseChanged||revealChanged);document.body.dataset.phase=state.game.phase;if(phaseChanged&&active()&&beforeView!==ui.view)$('#content')?.focus({preventScroll:true});
 }catch(e){
  if(version!==refreshVersion)return;
  setConnection(true);
  if(!state)app.innerHTML=`<div class="connection-lost"><h1>Connection interrupted</h1><p>${esc(e.message)}</p><button class="primary" data-action="retry">Try again</button></div>`;
 }
}
function cooldown(email,seconds){ui.resendUntil.set(email.trim().toLowerCase(),Date.now()+seconds*1000);updateResend();}
function clearWorkspace(){ui.openDetails.clear();ui.reportsCache.clear();ui.reportRound=null;ui.reportVillage=null;ui.selectedAssets=null;ui.draftTitle=null;ui.draftBody=null;ui.draftCredits=null;ui.draftVersion=null;ui.postFeedback='';ui.auth.pin='';ui.authMessage='';}
async function submitForm(form){
 const b=Object.fromEntries(new FormData(form));rememberAuth();
 if(form.id==='register-form'){
  authFeedback('Sending your PIN… Please keep this page open.');
  const result=await api('register',{name:b.name,email:b.email,village:b.village,role:b.role,consentEmail:!!b.consentEmail});
  ui.auth.email=result.email;ui.auth.pin='';cooldown(result.email,result.retryAfter);ui.tab='login';authFeedback(result.message);
 }else if(form.id==='login-form'){
  await api('login',{email:b.email,pin:b.pin});clearWorkspace();ui.view='home';notice('Welcome to your village!');
 }else if(form.id==='host-form'){
  await api('admin/login',{password:b.password});clearWorkspace();ui.view='admin';notice('Host session started');
 }else if(form.id==='mail-test-form'){
  ui.testEmail=b.email;ui.testSender=b.sender||'pin';const result=await api('admin/test-email',{email:b.email,sender:ui.testSender});ui.mailFeedback=result.message;notice(result.message);
 }else if(form.id==='enrol-form'){
  const result=await api('admin/enrol',{name:b.name,email:b.email,village:b.village,role:b.role,present:!!b.present,consentEmail:!!b.consentEmail});
  showPrivatePin(result);ui.enrol={name:'',email:'',village:b.village,role:'',present:false,consentEmail:false};notice('Account created. Hand the PIN to this participant privately.');
 }else if(form.id==='grant-form'){
  await api('action',{op:'grant',village:b.village,amount:Number(b.amount)});notice('Grant has been applied');
 }else if(form.id==='adjust-form'){
  const result=await api('action',{op:'adjustVillage',village:b.village,metric:b.metric,delta:Number(b.delta)});notice(result.message);
 }else if(form.id==='post-form'){
  const result=await api('action',{op:'publish',title:b.title,body:b.body,credits:b.credits,version:ui.draftVersion??state.posts.find(p=>p.village_id===state.me?.village_id)?.updated_at??0,assets:ui.selectedAssets??state.posts.find(p=>p.village_id===state.me?.village_id)?.assetIds??[]});
  notice(result.message||'Village campaign published');if(result.status!=='pending'){ui.draftTitle=null;ui.draftBody=null;ui.draftCredits=null;ui.draftVersion=null;}ui.postFeedback=result.message||'';
 }
 await refresh(true);
 if(form.id==='register-form')$('#login-form [name="pin"]')?.focus();
}
async function withBusy(button,work){
 if(ui.busy)return;ui.busy=true;if(button)button.disabled=true;
 try{await work();}finally{ui.busy=false;if(button?.isConnected)button.disabled=false;updateResend();}
}
async function action(el){
 if(ui.busy)return;const key=el.dataset.action;
 if(key==='set-ready'){await withBusy(el,async()=>{await api('action',{op:'setReady',ready:!state.ready});notice('Readiness saved. Only the host starts round one.');await refresh(true);});return;}
 if(['approveProposal','rejectProposal'].includes(key)){await withBusy(el,async()=>{const result=await api('action',{op:key,id:el.dataset.id});notice(result.message);await refresh(true);});return;}
 if(key==='resend-exercise'){await withBusy(el,async()=>{const result=await api('admin/resend-exercise',{playerId:el.dataset.id,sessionId:state.game.sessionId});notice(result.message);await refresh(true);});return;}
 if(key==='report-round'){ui.reportRound=Number(el.dataset.id);await loadReport(ui.reportRound);render(true);return;}
 if(key==='report-village'){ui.reportVillage=el.dataset.id;render(true);return;}
 if(key==='answer-security'){await withBusy(el,async()=>{await api('action',{op:'answerSecurity',id:el.dataset.id,answer:el.dataset.answer});notice('Response saved.');await refresh(true);});return;}
 if(key==='retry'){await refresh(true);return;}
 if(key==='copy-rescue-pin'){try{await navigator.clipboard.writeText($id('private-pin-value').textContent);notice('PIN copied.');}catch{notice('Select the displayed PIN to copy it.');}return;}
 if(key==='copy-invite'){
  try{await navigator.clipboard.writeText(state.invitationUrl);notice('Invitation link copied.');}
  catch{const details=el.closest('.invitation-card')?.querySelector('details');if(details)details.open=true;notice('Open the game link below, or press and hold it to copy.');}return;
 }
 if(key==='logout'){
  await withBusy(el,async()=>{await api('logout',{});clearWorkspace();ui.view='home';ui.tab='login';await refresh(true);});return;
 }
 if(key==='resend-pin'){
  const emailField=$('#login-form [name="email"]');if(!emailField?.reportValidity())return;
  rememberAuth();const email=ui.auth.email.trim().toLowerCase();
  await withBusy(el,async()=>{
   el.textContent='Sending PIN…';authFeedback('Requesting a new PIN… Please wait.');
   try{const result=await api('resend',{email});cooldown(email,result.retryAfter);ui.auth.pin='';const pin=$('#login-form [name=pin]');if(pin)pin.value='';authFeedback(result.message);}
   catch(e){if(e.retryAfter)cooldown(email,e.retryAfter);authFeedback(e.message,true);}
  });return;
 }
 if(key==='join-next-game'){await api('logout',{});clearWorkspace();await refresh(true);return;}
 if(key==='open-final-report'){showFinalReport();return;}
 if(key==='acknowledge-final-report'){
  await withBusy(el,async()=>{await api('action',{op:'acknowledgeReport'});$id('final-report-dialog')?.close();ui.view='home';await refresh(true);});return;
 }
 if(key==='wipe-data'){
  if(!confirm('Reset this finished session? Accounts and activities will be removed. Saved reports and report emails will be retained.'))return;
  const answer=prompt('Type RESET FINISHED GAME to confirm:');if(answer!=='RESET FINISHED GAME')return;
  const password=prompt('Enter the host password again:');if(!password)return;
  await withBusy(el,async()=>{await api('admin/reset-game',{confirm:answer,password,sessionId:state.game.sessionId});clearWorkspace();notice('Session reset. Final reports retained.');ui.view='admin';await refresh(true);});return;
 }
 if(key==='issue-pin'){
  if(!confirm('Issue a new temporary PIN for this player? Their previous PIN will stop working.'))return;
  await withBusy(el,async()=>{const out=await api('admin/issue-pin',{playerId:el.dataset.id});showPrivatePin(out);notice('Emergency PIN generated');});return;
 }
 if(key==='reload-campaign'){if(!confirm('Replace your local draft with the latest published campaign? Copy any text you want to keep first.'))return;ui.draftTitle=null;ui.draftBody=null;ui.draftCredits=null;ui.draftVersion=null;ui.selectedAssets=null;ui.postFeedback='';await refresh(true);return;}
 if(key==='asset'){
  ui.draftVersion??=state.posts.find(p=>p.village_id===state.me?.village_id)?.updated_at||0;
  const id=el.dataset.id,old=ui.selectedAssets??[...(state.posts.find(p=>p.village_id===state.me?.village_id)?.assetIds||[])];
  ui.selectedAssets=old.includes(id)?old.filter(x=>x!==id):old.length<5?[...old,id]:old;render(true);return;
 }
 if(['invest','chooseNews','unchooseNews','claimTask','releaseTask','helpTask','start','next','pause','resume','revealNews','revealMedia','shock','triggerTicket','end','closeRound','pauseCrisis','resumeCrisis','cancelCrisis'].includes(key)){
  const messages={cancelCrisis:'Cancel this crisis? Completed funding cuts are refunded; festival emergency tasks are withdrawn.',closeRound:'Close this round, evaluate decisions and save the village reports?',next:'Open the next round? The saved reports remain available.',revealNews:'Reveal the news results? Village selections will be locked.',revealMedia:'Reveal the usage review? Campaign editing will be locked.',shock:'Apply the 30% funding cut to all villages?',end:'End this session permanently and save everyone’s final report? It cannot be resumed. Choose Cancel and use Pause game if you only need a break.'};
  if(messages[key]&&!confirm(messages[key]))return;
  await withBusy(el,async()=>{const result=await api('action',{op:key,id:el.dataset.id});notice(result.message||({claimTask:'Task claimed. Your name is shown on the card; progress advances on server ticks.',releaseTask:'Task released. A teammate can claim it.',helpTask:'Help applied. You can help this task again in one minute.'}[key])||'Game state updated');await refresh(true);});
 }
}
document.addEventListener('click',async e=>{
 const tab=e.target.closest('[data-tab]'),view=e.target.closest('[data-view]'),btn=e.target.closest('[data-action]');if(ui.busy)return;
 if(tab){rememberAuth();ui.tab=tab.dataset.tab;authFeedback('');render(true);return;}
 if(view){ui.view=view.dataset.view;try{if(ui.view==='results')await loadReport();render(true);}catch(err){notice(err.message,true);}return;}
 if(btn){try{await action(btn);}catch(err){notice(err.message,true);}}
});
document.addEventListener('submit',async e=>{
 const f=e.target;if(!['register-form','login-form','host-form','grant-form','adjust-form','post-form','mail-test-form','enrol-form'].includes(f.id))return;
 e.preventDefault();if(ui.busy)return;
 const btn=f.querySelector('[type=submit]'),label=btn?.innerHTML;
 await withBusy(btn,async()=>{
  if(btn)btn.textContent=f.id==='register-form'?'Sending your PIN…':'Please wait…';
  try{await submitForm(f);}catch(err){if(['register-form','login-form','host-form'].includes(f.id))authFeedback(err.message,true);else {if(f.id==='post-form'){ui.postFeedback=err.message;const box=$id('post-feedback');if(box)box.textContent=err.message;}if(f.id==='mail-test-form'){ui.mailFeedback=err.message;await refresh(true);}notice(err.message,true);}}
  finally{if(btn?.isConnected)btn.innerHTML=label;}
 });
});
document.addEventListener('change',e=>{
 rememberAuth();rememberHostSupport(e.target);
 if(e.target.closest('#mail-test-form')&&e.target.name==='sender')render(true);
 if(e.target.id==='enrol-village'){ui.enrol.role='';render(true);}
 if(e.target.id==='register-village'){ui.village=e.target.value;ui.role='';render(true);}
 if(e.target.id==='register-role')ui.role=e.target.value;
 if(e.target.closest('#grant-form')&&e.target.name==='village')ui.adminGrantVillage=e.target.value;
 if(e.target.id==='metric'){ui.metric=e.target.value;render(true);}
 if(e.target.id==='news-filter'){ui.newsFilter=e.target.value;render(true);}
});
function rememberHostSupport(target){const f=target.closest('form');if(f?.id==='adjust-form')ui.adjustment=Object.fromEntries(new FormData(f));if(f?.id==='enrol-form'){const b=Object.fromEntries(new FormData(f));ui.enrol={...ui.enrol,...b,present:!!b.present,consentEmail:!!b.consentEmail};}if(f?.id==='mail-test-form'){ui.testEmail=f.elements.email.value;ui.testSender=f.elements.sender.value;}}
document.addEventListener('input',e=>{
 rememberHostSupport(e.target);
 if(e.target.closest('#register-form, #login-form')){rememberAuth();if(e.target.name==='email'){authFeedback('');updateResend();}}
 if(e.target.closest('#grant-form')&&e.target.name==='amount')ui.adminGrantAmount=e.target.value;
 if(e.target.closest('#post-form')){
  const f=e.target.closest('form');ui.draftVersion??=state.posts.find(p=>p.village_id===state.me?.village_id)?.updated_at||0;ui.draftTitle=f.elements.title.value;ui.draftBody=f.elements.body.value;ui.draftCredits=f.elements.credits?.value||'';
  const title=$id('preview-title'),body=$id('preview-body');if(title)title.textContent=f.elements.title.value||'Your village is waiting';if(body)body.textContent=(f.elements.body.value||'Your incredible adventure starts here.').slice(0,180);const credits=$id('preview-credits');if(credits)credits.textContent=f.elements.credits?.value||'';
 }
});
function syncValidity(e){const input=e.target;if(!input.matches?.('input,textarea,select'))return;if(input.matches(':user-invalid'))input.setAttribute('aria-invalid','true');else input.removeAttribute('aria-invalid');}
document.addEventListener('blur',syncValidity,true);document.addEventListener('input',syncValidity);
window.addEventListener('offline',()=>setConnection(true));window.addEventListener('online',()=>refresh());
$id('private-pin')?.addEventListener('close',()=>{$id('private-pin-value').textContent='';$id('private-pin-person').textContent='';});
function showFinalReport(){
 let dialog=$id('final-report-dialog');
 if(!dialog){dialog=document.createElement('dialog');dialog.id='final-report-dialog';dialog.className='final-report-dialog';dialog.setAttribute('aria-label','Final personal report');document.body.append(dialog);}
 dialog.innerHTML=renderFinalReport(state.finalReport)+`<button type="button" class="primary" data-action="acknowledge-final-report">OK — return to home</button>`;
 dialog.showModal();
}
const reportToken=new URL(location.href).searchParams.get('report');
if(reportToken){
 try{const report=await api('final-report?token='+encodeURIComponent(reportToken));app.innerHTML=renderFinalReport(report);}catch(e){app.textContent=e.message;}
}else {await refresh(true);setInterval(()=>refresh(),3500);setInterval(updateResend,1000);setInterval(updateRoundClock,1000);}
